// Adds the translation of `key` to an { en, mr, ... } entry for every language that does not have it yet.
export function fill(entry, key) {
  if (!entry) return entry;
  for (const [code, t] of Object.entries(TR)) if (!entry[code] && t[key]) entry[code] = t[key];
  return entry;
}
